describe('Polling Stopping on Navigation', () => {
  beforeEach(() => {
    cy.visit('/polling-page');
  });

  it('should stop polling when user navigates away from the page', () => {
    // Setup: Start polling
    cy.intercept('GET', '/api/data', (req) => {
      req.reply((res) => {
        res.delay(1000);
        res.send({
          statusCode: 200,
          body: {
            data: 'Polling data',
            timestamp: Date.now()
          }
        });
      });
    }).as('getPollingData');

    // Verify polling is active
    cy.get('[data-testid="polling-status"]').should('be.visible');
    cy.get('[data-testid="polling-status"]').should('contain', 'Polling...');

    // Verify polling interval is set
    cy.get('[data-testid="polling-interval"]').should('be.visible');
    cy.get('[data-testid="polling-interval"]').should('contain', '1000ms');

    // Verify polling is working
    cy.wait('@getPollingData');
    cy.get('[data-testid="polling-status"]').should('contain', 'Polling...');

    // Navigate away from the page
    cy.get('[data-testid="nav-link"]').click();

    // Verify polling stops
    cy.get('[data-testid="polling-status"]').should('not.exist');
    cy.get('[data-testid="polling-interval"]').should('not.exist');

    // Verify no polling requests are made
    cy.intercept('GET', '/api/data', {
      statusCode: 200,
      body: {
        data: 'No polling data',
        timestamp: Date.now()
      }
    }).as('getPollingDataAfterNavigation');

    cy.wait('@getPollingDataAfterNavigation');
    cy.get('[data-testid="polling-status"]').should('not.exist');
  });

  it('should handle edge case where polling is interrupted by navigation', () => {
    // Setup: Start polling
    cy.intercept('GET', '/api/data', (req) => {
      req.reply((res) => {
        res.delay(500);
        res.send({
          statusCode: 200,
          body: {
            data: 'Polling data',
            timestamp: Date.now()
          }
        });
      });
    }).as('getPollingData');

    // Verify polling is active
    cy.get('[data-testid="polling-status"]').should('be.visible');
    cy.get('[data-testid="polling-status"]').should('contain', 'Polling...');

    // Verify polling interval is set
    cy.get('[data-testid="polling-interval"]').should('be.visible');
    cy.get('[data-testid="polling-interval"]').should('contain', '1000ms');

    // Verify polling is working
    cy.wait('@getPollingData');
    cy.get('[data-testid="polling-status"]').should('contain', 'Polling...');

    // Navigate away from the page
    cy.get('[data-testid="nav-link"]').click();

    // Verify polling stops immediately
    cy.get('[data-testid="polling-status"]').should('not.exist');
    cy.get('[data-testid="polling-interval"]').should('not.exist');

    // Verify no polling requests are made
    cy.intercept('GET', '/api/data', {
      statusCode: 200,
      body: {
        data: 'No polling data',
        timestamp: Date.now()
      }
    }).as('getPollingDataAfterNavigation');

    cy.wait('@getPollingDataAfterNavigation');
    cy.get('[data-testid="polling-status"]').should('not.exist');
  });
});
